'use strict';

// Protects composition against shared globals, sibling resets, layout shifts,
// external resources and script coupling. Isolated component checks cannot
// expose interactions between all three real scripts or one absent sibling.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { pathToFileURL } = require('node:url');
const { chromium } = require('C:\\Users\\oren\\codex-harness\\ui\\node_modules\\.pnpm\\playwright-core@1.59.1\\node_modules\\playwright-core');

const root = path.resolve(__dirname, '..');
const fileURL = relative => pathToFileURL(path.join(root, relative)).href;
const pageURL = fileURL('index.html');
const evidence = process.env.SELDON_EVIDENCE_DIR;
assert.ok(evidence, 'SELDON_EVIDENCE_DIR must identify a writable evidence directory');
fs.mkdirSync(evidence, { recursive: true });

const components = [
  { id: 'hello', name: 'Play hello', text: 'Hello, world!' },
  { id: 'name', name: 'Play introduction', text: 'My name is Seldon' },
  { id: 'foundation', name: 'Play Foundation', text: 'This is the Foundation' },
];
const report = { passed: false, pageURL, cases: [] };

async function snapshot(page) {
  return page.evaluate(ids => {
    const bounds = node => {
      const { x, y, width, height } = node.getBoundingClientRect();
      return { x, y, width, height };
    };
    return {
      overflow: Math.max(document.documentElement.scrollWidth, document.body.scrollWidth) > innerWidth,
      pieces: ids.map(id => {
        const message = document.getElementById(`${id}-message`);
        const button = document.getElementById(`${id}-button`);
        const style = getComputedStyle(message);
        return {
          id, hidden: message.hidden, text: message.textContent,
          visible: message.getClientRects().length > 0 && style.visibility === 'visible',
          count: document.querySelectorAll(`[id="${id}-message"]`).length,
          button: bounds(button), message: bounds(message),
          exposed: !message.closest('[hidden], [aria-hidden="true"]'),
        };
      }),
    };
  }, components.map(component => component.id));
}

function verifyState(state, revealed, original, viewport, label) {
  assert.equal(state.overflow, false, `${label}: no horizontal overflow`);
  for (const [i, piece] of state.pieces.entries()) {
    const expected = revealed.has(piece.id);
    assert.equal(piece.count, 1, `${label}: one ${piece.id} target`);
    assert.equal(piece.hidden, !expected, `${label}: ${piece.id} hidden state`);
    assert.equal(piece.visible, expected, `${label}: ${piece.id} rendered state`);
    assert.equal(piece.text, expected ? components[i].text : '', `${label}: exact ${piece.id} text`);
    if (expected) {
      assert.ok(piece.exposed, `${label}: ${piece.id} accessible to assistive technology`);
      assert.ok(piece.message.x >= 0 && piece.message.x + piece.message.width <= viewport.width + 0.5,
        `${label}: ${piece.id} message fits horizontally`);
      assert.ok(piece.message.y >= 0 && piece.message.y + piece.message.height <= viewport.height + 0.5,
        `${label}: ${piece.id} message fits screenshot`);
    }
    for (const axis of ['x', 'y', 'width', 'height']) {
      assert.ok(Math.abs(piece.button[axis] - original.pieces[i].button[axis]) < 0.5,
        `${label}: ${piece.id} control ${axis} stays fixed`);
    }
  }
}

async function bodyOutside(page, target) {
  return page.evaluate(id => {
    const body = document.body.cloneNode(true);
    body.querySelector(`#${id}-message`).replaceWith(document.createComment('activation target'));
    return body.innerHTML;
  }, target);
}

async function checkCase(browser, viewport, omitted = null) {
  const label = `${viewport.width}x${viewport.height}-${omitted ? `omit-${omitted}` : 'complete'}`;
  const result = {
    label, omitted, passed: false, networkRequests: [], pageErrors: [], consoleErrors: [],
    failedResources: [], dialogs: [], navigations: [], popups: [], substitutions: [],
    requests: [], screenshots: [], activations: [],
  };
  report.cases.push(result);
  const context = await browser.newContext({ viewport, reducedMotion: 'reduce', serviceWorkers: 'block' });
  let page;
  try {
    context.setDefaultTimeout(10000);
    context.setDefaultNavigationTimeout(10000);
    const allowedResources = [pageURL, fileURL('styles.css'), ...components.map(c => fileURL(`scripts/${c.id}.js`))];
    const omittedURL = omitted ? fileURL(`scripts/${omitted}.js`) : null;
    let admittedDocument = false;
    context.on('request', request => {
      const url = request.url();
      result.requests.push({ url, type: request.resourceType() });
      if (/^https?:/i.test(url)) result.networkRequests.push({ url, method: request.method() });
    });
    context.on('requestfailed', request => {
      result.failedResources.push({ url: request.url(), error: request.failure()?.errorText });
    });
    context.on('response', response => {
      if (response.status() >= 400) result.failedResources.push({ url: response.url(), status: response.status() });
    });
    await context.route('**/*', async route => {
      const request = route.request();
      const url = request.url();
      // Every HTTP(S) attempt is recorded by the request listener and denied.
      if (/^https?:/i.test(url)) return route.abort('blockedbyclient');
      if (request.isNavigationRequest()) {
        if (url !== pageURL || admittedDocument) return route.abort('blockedbyclient');
        admittedDocument = true;
      }
      if (url === omittedURL) {
        result.substitutions.push(url);
        assert.equal(result.substitutions.length, 1, `${label}: replace exactly one script request`);
        return route.fulfill({ status: 200, contentType: 'text/javascript', body: '' });
      }
      return route.continue();
    });
    page = await context.newPage();
    const observePage = observed => {
      observed.on('pageerror', error => result.pageErrors.push(error.message));
      observed.on('console', message => {
        if (message.type() === 'error') result.consoleErrors.push(message.text());
      });
      observed.on('dialog', async dialog => {
        result.dialogs.push({ type: dialog.type(), message: dialog.message() });
        await dialog.dismiss();
      });
      observed.on('framenavigated', frame => result.navigations.push(frame.url()));
    };
    observePage(page);
    context.on('page', popup => {
      result.popups.push(popup.url());
      observePage(popup);
    });
    await page.goto(pageURL, { waitUntil: 'load' });
    assert.equal(page.url(), pageURL, `${label}: canonical file URL`);
    assert.equal(await page.getByRole('button').count(), 3, `${label}: three native controls`);
    for (const component of components) {
      const button = page.getByRole('button', { name: component.name, exact: true });
      assert.equal(await button.count(), 1, `${label}: distinct ${component.id} accessible name`);
      assert.equal(await button.evaluate(node => node.tagName), 'BUTTON');
      assert.equal(await button.getAttribute('aria-controls'), `${component.id}-message`);
      const region = page.locator(`#${component.id}-message`).locator('..');
      assert.equal(await region.getAttribute('aria-live'), 'polite');
      assert.equal(await region.getAttribute('aria-atomic'), 'true');
    }
    const scripts = await page.locator('script').evaluateAll(nodes => nodes.map(node => ({
      src: node.src, type: node.type, inline: node.textContent.trim(),
    })));
    assert.deepEqual(scripts, components.map(c => ({ src: fileURL(`scripts/${c.id}.js`), type: '', inline: '' })),
      `${label}: actual three classic component scripts`);
    const initial = await snapshot(page);
    result.initialControls = initial.pieces.map(piece => piece.button);
    const revealed = new Set();
    verifyState(initial, revealed, initial, viewport, label);
    for (let i = 0; i < initial.pieces.length; i++) {
      const control = initial.pieces[i].button;
      assert.ok(control.x >= 0 && control.x + control.width <= viewport.width + 0.5 &&
        control.y >= 0 && control.y + control.height <= viewport.height, `${label}: control in viewport`);
      assert.ok(control.width >= 44 && control.height >= 44, `${label}: usable target`);
      if (i) {
        const previous = initial.pieces[i - 1].button;
        assert.ok(control.x > previous.x + previous.width, `${label}: side-by-side controls`);
        assert.ok(Math.abs(control.y - previous.y) < 0.5, `${label}: aligned controls`);
        assert.ok(Math.abs(control.width - previous.width) < 0.5, `${label}: equal control widths`);
      }
    }
    const [a, b, c] = initial.pieces.map(piece => piece.button);
    assert.ok(Math.abs((b.x - a.x - a.width) - (c.x - b.x - b.width)) < 0.5,
      `${label}: even spacing`);
    if (!omitted) {
      const filename = `integration-${viewport.width}x${viewport.height}-initial.png`;
      await page.screenshot({ path: path.join(evidence, filename) });
      result.screenshots.push(filename);
    }

    // A non-DOM activation order and a repeated reverse pass exercise both
    // hidden and revealed sibling states, catching resets and duplicate text.
    for (const id of ['name', 'hello', 'foundation', 'foundation', 'hello', 'name']) {
      const before = await bodyOutside(page, id);
      await page.getByRole('button', { name: components.find(c => c.id === id).name, exact: true }).click();
      if (id !== omitted) revealed.add(id);
      verifyState(await snapshot(page), revealed, initial, viewport, `${label} after ${id}`);
      assert.equal(await bodyOutside(page, id), before, `${label}: ${id} changes only its message`);
      result.activations.push(id);
    }
    if (!omitted) {
      const filename = `integration-${viewport.width}x${viewport.height}-revealed.png`;
      await page.screenshot({ path: path.join(evidence, filename) });
      result.screenshots.push(filename);
    }
    assert.deepEqual(result.substitutions, omitted ? [omittedURL] : [], `${label}: only the designated omission`);
    assert.deepEqual(result.requests.map(request => request.url).sort(), [...allowedResources].sort(),
      `${label}: HTML, CSS and each real script requested exactly once; no extra resources`);
    assert.deepEqual(result.networkRequests, [], `${label}: zero attempted HTTP(S) requests`);
    assert.deepEqual(result.failedResources, [], `${label}: no failed resources`);
    assert.deepEqual(result.pageErrors, [], `${label}: no page errors`);
    assert.deepEqual(result.consoleErrors, [], `${label}: no console errors`);
    assert.deepEqual(result.dialogs, [], `${label}: no dialogs`);
    assert.deepEqual(result.navigations, [pageURL], `${label}: only initial document navigation`);
    assert.deepEqual(result.popups, [], `${label}: no popup navigation`);
    result.passed = true;
    console.log(`PASS ${label}: six sequential activations, exact sibling state, fixed controls, offline isolation`);
  } catch (error) {
    result.error = error.stack || String(error);
    if (page && !page.isClosed()) {
      const filename = `integration-${label}-failure.png`;
      await page.screenshot({ path: path.join(evidence, filename) }).then(() => result.screenshots.push(filename)).catch(() => {});
    }
    throw error;
  } finally {
    await context.close();
  }
}

(async () => {
  let browser;
  try {
    browser = await chromium.launch({
      headless: true,
      executablePath: 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe',
    });
    report.browserVersion = browser.version();
    for (const viewport of [{ width: 1280, height: 800 }, { width: 390, height: 844 }]) {
      await checkCase(browser, viewport);
    }
    for (const component of components) await checkCase(browser, { width: 1280, height: 800 }, component.id);
    report.passed = true;
  } finally {
    try {
      if (browser) await browser.close();
    } finally {
      fs.writeFileSync(path.join(evidence, 'integration-results.json'), `${JSON.stringify(report, null, 2)}\n`);
    }
  }
})().catch(error => { console.error(error); process.exitCode = 1; });

