'use strict';

// Protects the real file-page shell against unnamed controls, absent keyboard
// focus and overflowing mobile columns. Component checks do not cover this
// shared layout. No component behavior is supplied or credited by this check.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { pathToFileURL } = require('node:url');
const { chromium } = require('C:\\Users\\oren\\codex-harness\\ui\\node_modules\\.pnpm\\playwright-core@1.59.1\\node_modules\\playwright-core');

const root = path.resolve(__dirname, '..');
const evidence = process.env.SELDON_EVIDENCE_DIR;
assert.ok(evidence, 'SELDON_EVIDENCE_DIR must identify a writable evidence directory');
fs.mkdirSync(evidence, { recursive: true });
const components = [
  { id: 'hello', name: 'Play hello', script: 'hello.js' },
  { id: 'name', name: 'Play introduction', script: 'name.js' },
  { id: 'foundation', name: 'Play Foundation', script: 'foundation.js' },
];
const scripts = new Map(components.map(({ script }) => {
  const filename = path.join(root, 'scripts', script);
  return [pathToFileURL(filename).href.toLowerCase(), { filename, requests: 0, stubbed: !fs.existsSync(filename) }];
}));

async function checkViewport(browser, viewport) {
  const context = await browser.newContext({ viewport, reducedMotion: 'reduce' });
  const page = await context.newPage();
  const errors = [];
  const network = [];
  const label = `${viewport.width}x${viewport.height}`;
  page.on('pageerror', error => errors.push(error.message));
  page.on('console', message => { if (message.type() === 'error') errors.push(message.text()); });
  await context.route('**/*', async route => {
    const url = route.request().url();
    const component = scripts.get(url.toLowerCase());
    if (component) {
      component.requests++;
      if (component.stubbed) {
        // The only substituted requests: absent component scripts, empty bodies.
        return route.fulfill({ status: 200, contentType: 'text/javascript', body: '' });
      }
    }
    if (/^https?:/i.test(url)) {
      network.push(url);
      return route.abort();
    }
    return route.continue();
  });

  try {
    await page.goto(pathToFileURL(path.join(root, 'index.html')).href, { waitUntil: 'load' });
    assert.equal(await page.title(), 'Foundation');
    assert.equal(await page.getByRole('heading', { level: 1, name: 'Foundation', exact: true }).count(), 1);
    assert.equal(await page.getByRole('button').count(), 3);
    for (const component of components) {
      const button = page.getByRole('button', { name: component.name, exact: true });
      assert.equal(await button.count(), 1, `${component.id}: unique accessible button name`);
      assert.equal(await button.getAttribute('id'), `${component.id}-button`);
      assert.equal(await button.evaluate(node => node.tagName), 'BUTTON');
      assert.equal(await button.getAttribute('type'), 'button');
      assert.equal(await button.getAttribute('aria-controls'), `${component.id}-message`);
    }

    const shell = await page.evaluate(() => {
      const rect = node => {
        const { x, y, width, height, right, bottom } = node.getBoundingClientRect();
        return { x, y, width, height, right, bottom };
      };
      const rgb = color => color.match(/[\d.]+/g).slice(0, 3).map(Number);
      const luminance = color => rgb(color).map(value => {
        const channel = value / 255;
        return channel <= 0.04045 ? channel / 12.92 : ((channel + 0.055) / 1.055) ** 2.4;
      }).reduce((sum, value, i) => sum + value * [0.2126, 0.7152, 0.0722][i], 0);
      const contrast = (a, b) => {
        const values = [luminance(a), luminance(b)].sort((x, y) => y - x);
        return (values[0] + 0.05) / (values[1] + 0.05);
      };
      const canvas = getComputedStyle(document.body).backgroundColor;
      const heading = document.querySelector('h1');
      const range = document.createRange();
      range.selectNodeContents(heading);
      const textBounds = rect(range);
      return {
        canvas,
        headingFont: getComputedStyle(heading).fontFamily,
        headingBounds: textBounds,
        headingContrast: contrast(getComputedStyle(heading).color, canvas),
        overflow: Math.max(document.documentElement.scrollWidth, document.body.scrollWidth) > innerWidth,
        scripts: Array.from(document.scripts, script => ({
          source: script.getAttribute('src'), defer: script.defer, async: script.async, type: script.type,
        })),
        pieces: ['hello', 'name', 'foundation'].map(id => {
          const button = document.getElementById(`${id}-button`);
          const message = document.getElementById(`${id}-message`);
          const region = message.parentElement;
          const buttonStyle = getComputedStyle(button);
          const messageStyle = getComputedStyle(message);
          const headingStyle = getComputedStyle(button.parentElement.querySelector('h2'));
          const iconStyle = getComputedStyle(button.querySelector('.play-icon'));
          const regionStyle = getComputedStyle(region);
          return {
            id, button: rect(button), region: rect(region),
            hidden: message.hidden, messageCount: document.querySelectorAll(`#${id}-message`).length,
            empty: message.textContent === '', display: messageStyle.display,
            regionLive: region.getAttribute('aria-live'), regionHidden: region.hidden,
            regionVisible: regionStyle.display !== 'none' && regionStyle.visibility === 'visible',
            regionContainsOnlyOwnMessage: region.querySelectorAll('p').length === 1,
            regionFollowsButton: button.nextElementSibling === region,
            regionHasHiddenAncestor: Boolean(region.closest('[hidden], [aria-hidden="true"]')),
            buttonContrast: contrast(buttonStyle.color, buttonStyle.backgroundColor),
            borderContrast: contrast(buttonStyle.borderTopColor, buttonStyle.backgroundColor),
            messageContrast: contrast(messageStyle.color, canvas),
            titleContrast: contrast(headingStyle.color, canvas),
            iconContrast: contrast(iconStyle.borderLeftColor, buttonStyle.backgroundColor),
            buttonFont: buttonStyle.fontFamily, radius: buttonStyle.borderRadius,
            fontSize: parseFloat(messageStyle.fontSize), wrap: messageStyle.overflowWrap,
            whiteSpace: messageStyle.whiteSpace, transition: buttonStyle.transitionDuration,
          };
        }),
      };
    });

    assert.equal(shell.canvas, 'rgb(16, 16, 16)', 'ink-black canvas');
    assert.match(shell.headingFont, /^Georgia\b/, 'offline Georgia headline');
    assert.ok(shell.headingBounds.x >= 0 && shell.headingBounds.right <= viewport.width, 'heading fits viewport');
    assert.ok(shell.headingContrast >= 4.5, 'readable headline contrast');
    assert.equal(shell.overflow, false, 'no horizontal page overflow');
    assert.deepEqual(shell.scripts, components.map(({ script }) => ({
      source: `scripts/${script}`, defer: true, async: false, type: '',
    })), 'three independent classic deferred script references');

    const pieces = shell.pieces;
    for (const piece of pieces) {
      assert.equal(piece.messageCount, 1, `${piece.id}: unique message target`);
      assert.ok(piece.empty && piece.hidden && piece.display === 'none', `${piece.id}: initially empty and hidden`);
      assert.equal(piece.regionLive, 'polite', `${piece.id}: persistent polite live region`);
      assert.ok(!piece.regionHidden && piece.regionVisible && !piece.regionHasHiddenAncestor, `${piece.id}: live region stays rendered`);
      assert.ok(piece.regionContainsOnlyOwnMessage && piece.regionFollowsButton, `${piece.id}: owns its message beneath its control`);
      assert.ok(piece.region.y >= piece.button.bottom, `${piece.id}: message region below button`);
      assert.ok(Math.abs(piece.region.x - piece.button.x) < 1 && Math.abs(piece.region.width - piece.button.width) < 1, `${piece.id}: message stays in column`);
      assert.ok(piece.button.x >= 0 && piece.button.right <= viewport.width, `${piece.id}: control inside viewport`);
      assert.ok(piece.button.width >= 44 && piece.button.height >= 44, `${piece.id}: usable target size`);
      assert.match(piece.buttonFont, /^Arial\b/, `${piece.id}: Arial label`);
      assert.equal(piece.radius, '0px', `${piece.id}: crisp rectangular control`);
      assert.ok(piece.fontSize >= 16 && piece.wrap === 'anywhere' && piece.whiteSpace === 'normal', `${piece.id}: readable wrapping messages`);
      for (const key of ['buttonContrast', 'messageContrast', 'titleContrast']) {
        assert.ok(piece[key] >= 4.5, `${piece.id}: ${key} meets 4.5:1`);
      }
      assert.ok(piece.iconContrast >= 3 && piece.borderContrast >= 3, `${piece.id}: visible amber icon and boundary`);
      assert.equal(piece.transition, '0s', `${piece.id}: honors reduced motion`);
    }
    for (let i = 1; i < pieces.length; i++) {
      assert.ok(pieces[i].button.x > pieces[i - 1].button.right, 'ordered side-by-side controls');
      assert.ok(Math.abs(pieces[i].button.y - pieces[0].button.y) < 1, 'aligned control row');
      assert.ok(Math.abs(pieces[i].button.width - pieces[0].button.width) < 1, 'equal column widths');
    }
    const gaps = [pieces[1].button.x - pieces[0].button.right, pieces[2].button.x - pieces[1].button.right];
    assert.ok(Math.abs(gaps[0] - gaps[1]) < 1, 'even column spacing');
    await page.screenshot({ path: path.join(evidence, `shell-${label}.png`), fullPage: true });

    for (const component of components) {
      await page.keyboard.press('Tab');
      const focus = await page.evaluate(() => {
        const node = document.activeElement;
        const style = getComputedStyle(node);
        return {
          id: node.id, visible: node.matches(':focus-visible'),
          outline: style.outlineStyle, width: parseFloat(style.outlineWidth),
          offset: parseFloat(style.outlineOffset), color: style.outlineColor,
        };
      });
      assert.equal(focus.id, `${component.id}-button`, 'natural tab order');
      assert.ok(focus.visible && focus.outline === 'solid' && focus.width >= 3 && focus.offset >= 3, 'visible keyboard focus');
      assert.equal(focus.color, 'rgb(255, 244, 223)', 'warm-white high-contrast focus ring');
    }
    await page.screenshot({ path: path.join(evidence, `shell-focus-${label}.png`), fullPage: true });
    assert.deepEqual(network, [], 'page makes no network requests');
    assert.deepEqual(errors, [], 'page has no browser errors');
    console.log(`PASS shell ${label}: accessibility, focus, contrast, layout, offline load`);
  } catch (error) {
    await page.screenshot({ path: path.join(evidence, `shell-failure-${label}.png`), fullPage: true }).catch(() => {});
    throw error;
  } finally {
    await context.close();
  }
}

(async () => {
  let browser;
  try {
    browser = await chromium.launch({
      headless: true,
      executablePath: 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe',
    });
    for (const viewport of [{ width: 1280, height: 800 }, { width: 390, height: 844 }]) {
      await checkViewport(browser, viewport);
    }
    for (const [url, script] of scripts) {
      assert.equal(script.requests, 2, `each viewport requested ${url}`);
    }
    console.log(`Component scripts fulfilled empty only when absent: ${[...scripts.values()].filter(script => script.stubbed).length}/3`);
  } finally {
    if (browser) await browser.close();
  }
})().catch(error => { console.error(error); process.exitCode = 1; });

