:root {
  color-scheme: dark;
  --ink: #101010;
  --paper: #fff4df;
  --amber: #ffbb46;
  background: var(--ink);
  color: var(--paper);
  font-family: Arial, sans-serif;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  background: var(--ink);
}

main {
  width: min(100%, 1280px);
  margin-inline: auto;
  padding: 76px 80px 48px;
}

.masthead { margin-bottom: 108px; }

.eyebrow {
  margin: 0 0 24px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-family: Georgia, serif;
  font-size: clamp(60px, 10vw, 128px);
  font-weight: 400;
  letter-spacing: -0.055em;
  line-height: 1.05;
}

.signals {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 32px;
}

.signal {
  min-width: 0;
  border-top: 1px solid var(--paper);
  padding-top: 18px;
}

.number {
  margin: 0 0 28px;
  color: var(--amber);
  font-size: 12px;
  letter-spacing: 0.08em;
}

h2 {
  margin: 0 0 24px;
  font-size: 28px;
  font-weight: 400;
  letter-spacing: -0.025em;
  line-height: 1.2;
}

button {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 18px;
  width: 100%;
  min-height: 96px;
  padding: 20px 12px;
  border: 1px solid var(--amber);
  border-radius: 0;
  background: var(--ink);
  color: var(--paper);
  font: 400 18px/1.2 Arial, sans-serif;
  cursor: pointer;
  transition: background-color 120ms linear;
}

.play-icon {
  display: block;
  flex: 0 0 auto;
  width: 0;
  height: 0;
  border-top: 12px solid transparent;
  border-bottom: 12px solid transparent;
  border-left: 20px solid var(--amber);
